class GoldMiner {
  constructor() {
    this.score = 0;
    this.time = 60;
    this.hookAngle = 0;
    this.hookLength = 0;
    this.isShooting = false;
    this.isRetracting = false;
    this.items = [];
    this.hookSpeed = 5;
    this.caughtItemValue = 0;
    this.hookBaseX = 400;
    this.hookBaseY = 300;
  }

  launchHook() {
    if (this.isShooting || this.isRetracting) return;
    this.isShooting = true;
    this.hookSpeed = 5;
  }

  update(deltaTime = 1/60) {
    if (this.isShooting) {
      this.hookLength += this.hookSpeed * deltaTime * 60;
      if (this.hookLength >= 300) {
        this.hookLength = 300;
        this.isShooting = false;
        this.isRetracting = true;
      }
      for (let item of this.items) {
        if (!item.isCaught && this.checkCollision(item)) {
          this.catchItem(item);
          this.isShooting = false;
          break;
        }
      }
    }
    if (this.isRetracting) {
      let speedFactor = this.caughtItemValue > 0 ? 0.5 : 1;
      this.hookLength -= this.hookSpeed * speedFactor * deltaTime * 60;
      if (this.caughtItemValue > 0) {
        const caughtItem = this.items.find(item => item.isCaught && !item.scoreAdded);
        if (caughtItem) {
          caughtItem.x = this.getHookEndX();
          caughtItem.y = this.getHookEndY();
        }
      }
      if (this.hookLength <= 0) {
        this.hookLength = 0;
        this.isRetracting = false;
        this.score += this.caughtItemValue || 0;
        const caughtItem = this.items.find(item => item.isCaught && !item.scoreAdded);
        if (caughtItem) {
          caughtItem.isCaught = false;
          caughtItem.scoreAdded = true;
        }
        this.caughtItemValue = 0;
      }
    }
    this.time -= deltaTime;
  }

  getHookEndX() {
    return this.hookBaseX + Math.cos(this.hookAngle) * this.hookLength;
  }

  getHookEndY() {
    return this.hookBaseY + Math.sin(this.hookAngle) * this.hookLength;
  }

  checkCollision(item) {
    let hookX = this.getHookEndX();
    let hookY = this.getHookEndY();
    let dx = hookX - item.x;
    let dy = hookY - item.y;
    let distance = Math.sqrt(dx * dx + dy * dy);
    return distance < item.radius + 10;
  }

  catchItem(item) {
    this.caughtItemValue = item.value;
    item.isCaught = true;
    this.isRetracting = true;
  }

  addItem(item) {
    if (!this.items.find(i => i.id === item.id)) {
      this.items.push(item);
    }
  }

  removeItem(itemId) {
    this.items = this.items.filter(item => item.id === itemId);
  }

  getScore() { return this.score; }
  getTime() { return Math.max(0, this.time); }
  setHookAngle(angle) { this.hookAngle = angle; }
  isGameOver() { return this.time <= 0; }
  reset() {
    this.score = 0;
    this.time = 60;
    this.hookLength = 0;
    this.isShooting = false;
    this.isRetracting = false;
    this.caughtItemValue = 0;
    this.items.forEach(item => {
      item.isCaught = false;
      item.scoreAdded = false;
    });
  }
}
